-- 1. CRIAR ESTRUTURA DAS TABELAS
CREATE TABLE IF NOT EXISTS categories (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT NOT NULL,
  icon TEXT NOT NULL,
  color TEXT NOT NULL,
  sort_order INT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS places (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  address TEXT NOT NULL,
  lat DOUBLE PRECISION NOT NULL,
  lng DOUBLE PRECISION NOT NULL,
  category_id TEXT REFERENCES categories(id) ON DELETE CASCADE,
  hours TEXT,
  contact TEXT,
  photos JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS reviews (
  id TEXT PRIMARY KEY,
  place_id TEXT REFERENCES places(id) ON DELETE CASCADE,
  author TEXT NOT NULL,
  rating INT NOT NULL,
  comment TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE places ENABLE ROW LEVEL SECURITY;
ALTER TABLE reviews ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Leitura publica categorias" ON categories;
CREATE POLICY "Leitura publica categorias" ON categories FOR SELECT USING (true);

DROP POLICY IF EXISTS "Leitura publica locais" ON places;
CREATE POLICY "Leitura publica locais" ON places FOR SELECT USING (true);

DROP POLICY IF EXISTS "Leitura publica avaliacoes" ON reviews;
CREATE POLICY "Leitura publica avaliacoes" ON reviews FOR SELECT USING (true);

DROP POLICY IF EXISTS "Escrita categorias" ON categories;
CREATE POLICY "Escrita categorias" ON categories FOR ALL USING (true);

DROP POLICY IF EXISTS "Escrita locais" ON places;
CREATE POLICY "Escrita locais" ON places FOR ALL USING (true);

DROP POLICY IF EXISTS "Escrita avaliacoes" ON reviews;
CREATE POLICY "Escrita avaliacoes" ON reviews FOR ALL USING (true);

